  --font-inter: "Inter", sans-serif;
  --font-space-grotesk: "Space Grotesk", sans-serif;
  --font-source-code-pro: "Source Code Pro", monospace;
  --code-block-collapsed-height: 6.5rem;
  --code-block-fade-height: 0.9375rem;
  --message-content-max-width: 80%;
  --alert-icon-width: calc(var(--spacing) * 4);
  --drawer-max-height: 80vh;

  --gradient-nordic: linear-gradient(
    -100deg,
    var(--nordic-50) 0%,
    var(--nordic-400) 44%,
    var(--nordic-200) 100%
  );
  --gradient-aurora: linear-gradient(
    -100deg,
    var(--aurora-50) 0%,
    var(--aurora-400) 50%,
    var(--aurora-200) 100%
  );
  --gradient-dusk: linear-gradient(
    -100deg,
    var(--dusk-50) 0%,
    var(--dusk-400) 48%,
    var(--dusk-200) 100%
  );
  --gradient-equinox: linear-gradient(
    -100deg,
    var(--dusk-600) 0%,
    var(--dusk-300) 40%,
    var(--aurora-50) 60%,
    var(--aurora-100) 100%
  );
  --gradient-summer: linear-gradient(
    -100deg,
    var(--nordic-100) 0%,
    var(--dusk-50) 50%,
    var(--aurora-100) 100%
  );
  --gradient-spring: linear-gradient(
    -100deg,
    var(--aurora-50) 0%,
    var(--nordic-100) 50%,
    var(--aurora-100) 100%
  );
  --gradient-fall: linear-gradient(
    -100deg,
    var(--fjord-550) 0%,
    var(--dusk-550) 50%,
    var(--dusk-300) 100%
