  --card-foreground: var(--foreground);
  --popover: var(--popover-background);
  --popover-foreground: var(--foreground);
  --primary: var(--primary-background);
  --primary-hover: var(--primary-background-hover);
  --primary-foreground: var(--foreground-on-primary);
  --secondary: var(--secondary-background);
  --secondary-hover: var(--secondary-background-hover);
  --muted: var(--muted-background);
  --accent: var(--active-muted-background);
  --accent-foreground: var(--active-foreground);
  --mountain: var(--muted-background);
  --mountain-foreground: var(--foreground);
  --foreground-link: var(--link-foreground);
  --input: var(--border);
  --ring-shadow: var(--ring-muted);
  --ring-destructive: var(--ring-critical);
  --ring-destructive-shadow: var(--ring-critical-shadow);
  --backdrop: var(--overlay-background);
