  --warning-foreground-alternate: var(--warning-foreground-on-warning);
  --warning-alternative: var(--warning-muted-background);
  --success-foreground-alternate: var(--success-foreground-on-success);
  --neutral-foreground-alternate: var(--neutral-foreground-on-neutral);
