  --decorative-background-hover-nordic: var(--decorative-nordic-background);
  --decorative-background-hover-aurora: var(--decorative-aurora-background-hover);
  --decorative-background-hover-dusk: var(--decorative-dusk-background-hover);
  --decorative-background-hover-orange: var(--decorative-orange-background-hover);
  --decorative-background-hover-sky: var(--decorative-sky-background-hover);
