  --gradient-aurora: linear-gradient(
    -100deg,
    var(--aurora-900) 0%,
    var(--aurora-600) 50%,
    var(--aurora-800) 100%
  );
  --gradient-dusk: linear-gradient(
    -100deg,
    var(--dusk-900) 0%,
